import os # Bound independent physical evaluation resources on the shared host.
os.environ['OMP_NUM_THREADS']='1';os.environ['OPENBLAS_NUM_THREADS']='1' # Avoid nested BLAS or finite-element oversubscription.
import argparse,hashlib,json,time,importlib,inspect # Preserve exact callback dispatch, source identity and elapsed cost.
from pathlib import Path # Resolve portable experiment evidence paths.
import numpy as np # Read raw predicted and native-reference physical fields without correction.
from complex_operator import ROOT,resolve_path,write,digest # Reuse only path and serialization utilities, not neural prediction or native label fitting.
def plain(value): # Convert scientific scalar metadata to finite JSON-compatible values.
    if isinstance(value,dict): return {str(key):plain(item) for key,item in value.items()} # Preserve each named independent physical diagnostic.
    if isinstance(value,(list,tuple)): return [plain(item) for item in value] # Keep every requested temporal record.
    if isinstance(value,np.ndarray): return plain(value.tolist()) # Preserve explicitly returned physical arrays when needed.
    if isinstance(value,(np.floating,np.integer,np.bool_)): return value.item() # Convert NumPy scalar values without stringification.
    if isinstance(value,float) and not np.isfinite(value): return str(value) # Record a nonfinite prediction diagnosis without producing invalid JSON.
    return value # Preserve ordinary finite Python metadata values unchanged.
def resolve_callback(family,row,index): # Resolve physical integration from the frozen actual source index and element contract.
    npz=resolve_path(row['npz']);metadata_path=resolve_path(row['metadata']);metadata=json.loads(metadata_path.read_text());solver=index.get('solver_module',index.get('solver_callback','').split('.')[0]);element=metadata.get('element_type','C3D8' if family=='friction' else None);raw=np.load(npz,allow_pickle=False) # Read physical input identities without changing any predicted field.
    if family=='friction': # This registered contact family uses the full eight-point trilinear solid check.
        assert element=='C3D8';module=importlib.import_module('complex_friction_checks');function=module.physical_metrics;invoke=lambda state:function(npz,metadata,state) # Preserve native projected-contact limitations and complete bulk integration.
    elif family=='rebar': # Require the exact registered material and integration adapter rather than a legacy family default.
        allowed={'complex_rebar_full27':'C3D20','complex_rebar_quadratic':'C3D20R','complex_rebar':'C3D8'};assert solver in allowed and element==allowed[solver],f'Unknown or mismatched rebar physical adapter: {solver}/{element}';module=importlib.import_module(solver);function=module.full_residual;invoke=lambda state:function(npz,state) # Use actual full27 integration and native MPCs for the selected final rebar mesh.
    elif family=='thermoplastic': # The versioned transient connector uses the producer's same geometry-independent C3D10 residual implementation.
        assert solver=='complex_thermoplastic_transient' and element=='C3D10' and 'transient' in metadata.get('family',''),'Unregistered thermal physical adapter';module=importlib.import_module('complex_thermoplastic_checks');function=module.physical_metrics;arrays=dict(raw);invoke=lambda state:function(arrays,metadata,states=state) # Preserve actual versioned thermal inputs and raw plastic SDVs without an old girder assumption.
    else: raise ValueError(f'Unsupported physical family: {family}') # Fail closed for an unimplemented constitutive or coupling mechanism.
    sources={str(Path(inspect.getsourcefile(function))):digest(inspect.getsourcefile(function))} # Identify the actual function implementation rather than only its import alias.
    if family=='rebar' and hasattr(module,'q'): sources[str(Path(module.q.__file__))]=digest(module.q.__file__) # Preserve the quadratic/full-integration helper implementation behind the thin callback wrapper.
    if family=='rebar': # Include the weak-form assembler and declared nonlinear traction law in the physical source identity.
        for dependency_name in ['complex_quadratic','complex_rebar']: dependency=importlib.import_module(dependency_name);sources[str(Path(dependency.__file__))]=digest(dependency.__file__) # Prevent a thin unchanged wrapper from hiding a changed material or integration implementation.
    provenance={'callback_module':module.__name__,'callback_function':function.__name__,'callback_source_sha256':sources,'native_solver_module':solver or 'complex_friction','metadata_sha256':digest(metadata_path),'metadata_element_type':metadata.get('element_type'),'effective_element_type':element,'graph_entity_count':int(raw['states'].shape[1]),'native_integration_point_count':metadata.get('native_solid_integration_points',metadata.get('integration_point_count',metadata.get('volume_IP_count')))} # Ground each callback in the exact native entity and integration-point contract.
    provenance['native_mesh_parameters']={key:metadata[key] for key in ['nx','cross_refinement','free_axial_cells','native_bond_points'] if key in metadata} # Preserve every actual reconstruction parameter rather than an obsolete default mesh.
    return invoke,provenance # Keep raw inference and numerical physics checking separate.
def run(family): # Evaluate only models already frozen and tested by the independent comparison pipeline.
    registry=json.loads((ROOT/'learning/campaign_learning_index.json').read_text());directory=ROOT/registry['families'][family];contract=json.loads((directory/'experiment_contract.json').read_text());frozen=json.loads((directory/'frozen_models_before_test.json').read_text());source=directory/'source_index.json';source=source if source.exists() else resolve_path(contract['source_index']);assert digest(source)==contract['source_index_sha256'],'Native index changed after experiment freeze';index=json.loads(source.read_text());rows={row['id']:row for row in index['cases']};records=[];started=time.monotonic() # Preserve fixed denominators and exact original native input identities.
    for strategy,model in frozen.items(): # Inspect raw initial, actively trained and matched-random model outputs separately.
        checkpoint=resolve_path(model['checkpoint']);assert digest(checkpoint)==model['sha256'],'Frozen model changed';metrics=json.loads((directory/'final_test'/strategy/'metrics.json').read_text()) # Require exact checkpoint identity before reading any reported physical prediction.
        for result in metrics['cases']: # Include every final test and OOD history, including models with poor field accuracy.
            row=rows[result['id']];prediction_file=directory/'final_test'/strategy/f"{row['id']}.npz";saved=np.load(prediction_file,allow_pickle=False);assert str(saved['npz_sha256'])==digest(resolve_path(row['npz'])),'Native field file changed';entry={'strategy':strategy,'id':row['id'],'split':row['split'],'checkpoint_sha256':model['sha256'],'prediction_sha256':digest(prediction_file),'reference_sha256':str(saved['npz_sha256']),'raw_neural_accuracy_pass':result['accuracy_pass'],'neural_correction_applied':False};case_started=time.monotonic() # Ground each physical check in the exact uncorrected neural tensor.
            entry['source_index_sha256']=digest(source) # Tie dispatch and fixed history selection to the exact frozen native index.
            try: invoke,provenance=resolve_callback(family,row,index);entry.update(provenance);entry['native_reference_physics']=plain(invoke(saved['reference']));entry['reference_adapter_status']='PASS_EXECUTED' # Sanity-check the adapter on the actual native reference before judging any neural field.
            except Exception as error: entry['evaluation_status']='PHYSICS_ADAPTER_OR_REFERENCE_ERROR';entry['reference_adapter_status']='ERROR';entry['error']=f'{type(error).__name__}: {error}' # Adapter failures are audit execution errors, never neural-versus-FEM negative examples.
            if entry['reference_adapter_status']=='PASS_EXECUTED': # Only a functioning reference adapter may evaluate the raw neural tensor.
                try: entry['raw_neural_physics']=plain(invoke(saved['prediction']));entry['evaluation_status']='COMPLETED' # Preserve each returned physical residual, including nonpositive deformation diagnostics.
                except Exception as error: entry['evaluation_status']='NEURAL_PHYSICS_EVALUATION_ERROR_UNCLASSIFIED';entry['error']=f'{type(error).__name__}: {error}' # Do not mistake an unexplained exception for proven structural failure or invent a finite physical residual.
            entry['seconds']=time.monotonic()-case_started;records.append(entry);write(directory/'physical_checks'/strategy/f"{row['id']}.json",entry);print(json.dumps({'family':family,'strategy':strategy,'id':row['id'],'status':entry['evaluation_status'],'seconds':entry['seconds']}),flush=True) # Save every actual result as it completes.
    summary={'family':family,'cases':records,'total_prediction_checks':len(records),'seconds':time.monotonic()-started,'raw_predictions_only':True,'native_reference_checked_by_same_callback':True,'complete_nonlinear_equilibrium_gate':'Not inferred from an accuracy metric; each physical callback explicitly states included and missing equations.','engineering_release':'HOLD'};write(directory/'physical_checks/summary.json',summary) # Retain mechanical consistency, field accuracy and project validation as distinct evidence.
if __name__=='__main__': # Run independent physics checks for one completed registered family.
    parser=argparse.ArgumentParser();parser.add_argument('--family',choices=['friction','rebar','thermoplastic'],required=True);run(parser.parse_args().family) # Require an explicit physical mechanism with an implemented independent callback.
